<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'

// The silhouette was traced and simplified from the PDF-compatible AI vector supplied by the site owner.
// Distribution paths depict broad coverage; endpoints are illustrative, not actual dealer addresses.
const selectedHub = ref<string | null>(null)
const hoveredHub = ref<string | null>(null)
const highlightedHub = computed(() => hoveredHub.value ?? selectedHub.value)
const toggleHub = (hub: string) => { selectedHub.value = selectedHub.value === hub ? null : hub }
const resetHub = () => { selectedHub.value = null; hoveredHub.value = null }

// The map runs about seventy endless animations. They only play while it is on the screen (or just about to be):
// elsewhere on the page they would repaint the drawing every frame for nobody.
const root = ref<HTMLElement | null>(null)
const svg = ref<SVGSVGElement | null>(null)
const onScreen = ref(true)
let observer: IntersectionObserver | null = null
onMounted(() => {
  if (!root.value || typeof IntersectionObserver === 'undefined') return
  observer = new IntersectionObserver(([entry]) => {
    if (!entry) return
    onScreen.value = entry.isIntersecting
    if (entry.isIntersecting) svg.value?.unpauseAnimations?.()
    else svg.value?.pauseAnimations?.()
  }, { rootMargin: '160px 0px' })
  observer.observe(root.value)
})
onBeforeUnmount(() => observer?.disconnect())
</script>

